    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def countGoodIntegers(self, n: int, k: int) -> int:\n        dictionary = set()\n        base = 10 ** ((n - 1) // 2)\n        skip = n & 1\n        # \u679a\u4e3e n \u4e2a\u6570\u4f4d\u7684\u56de\u6587\u6570\n        for i in range(base, base * 10):\n            s = str(i)\n            s += s[::-1][skip:]\n            palindromicInteger = int(s)\n            # \u5982\u679c\u5f53\u524d\u56de\u6587\u6570\u662f k \u56de\u6587\u6570 \n            if palindromicInteger % k == 0:\n                sorted_s = ''.join(sorted(s))\n                dictionary.add(sorted_s)\n\n        fac = [factorial(i) for i in range(n + 1)]\n        ans = 0\n        for s in dictionary:\n            cnt = [0] * 10\n            for c in s:\n                cnt[int(c)] += 1\n            # \u8ba1\u7b97\u6392\u5217\u7ec4\u5408\n            tot = (n - cnt[0]) * fac[n - 1]\n            for x in cnt:\n                tot //= fac[x]\n            ans += tot\n\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.countGoodIntegers(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
