    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def solveSudoku(self, board: List[List[str]]) -> None:\n        def dfs(pos: int):\n            nonlocal valid\n            if pos == len(spaces):\n                valid = True\n                return\n            \n            i, j = spaces[pos]\n            for digit in range(9):\n                if line[i][digit] == column[j][digit] == block[i // 3][j // 3][digit] == False:\n                    line[i][digit] = column[j][digit] = block[i // 3][j // 3][digit] = True\n                    board[i][j] = str(digit + 1)\n                    dfs(pos + 1)\n                    line[i][digit] = column[j][digit] = block[i // 3][j // 3][digit] = False\n                if valid:\n                    return\n            \n        line = [[False] * 9 for _ in range(9)]\n        column = [[False] * 9 for _ in range(9)]\n        block = [[[False] * 9 for _a in range(3)] for _b in range(3)]\n        valid = False\n        spaces = list()\n\n        for i in range(9):\n            for j in range(9):\n                if board[i][j] == \".\":\n                    spaces.append((i, j))\n                else:\n                    digit = int(board[i][j]) - 1\n                    line[i][digit] = column[j][digit] = block[i // 3][j // 3][digit] = True\n\n        dfs(0)\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.solveSudoku(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
