    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def numberOfPairs(self, points: List[List[int]]) -> int:\n        ans = 0\n        points.sort(key=lambda x: (x[0], -x[1]))\n\n        for i in range(len(points) - 1):\n            pointA = points[i]\n            xMin = pointA[0] - 1\n            xMax = math.inf\n            yMin = -math.inf\n            yMax = pointA[1] + 1\n\n            for j in range(i + 1, len(points)):\n                pointB = points[j]\n                if (pointB[0] > xMin and pointB[0] < xMax and\n                    pointB[1] > yMin and pointB[1] < yMax):\n                    ans += 1\n                    xMin = pointB[0]\n                    yMin = pointB[1]\n\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.numberOfPairs(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
