    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def tilingRectangle(self, n: int, m: int) -> int:\n        def dfs(x: int, y: int, cnt: int) -> None:\n            nonlocal ans\n            if cnt >= ans:\n                return\n            if x >= n:\n                ans = cnt\n                return\n            \n            # \u68c0\u6d4b\u4e0b\u4e00\u884c\n            if y >= m:\n                dfs(x + 1, 0, cnt)\n                return\n            # \u5982\u5f53\u524d\u5df2\u7ecf\u88ab\u8986\u76d6\uff0c\u5219\u76f4\u63a5\u5c1d\u8bd5\u4e0b\u4e00\u4e2a\u4f4d\u7f6e\n            if rect[x][y]:\n                dfs(x, y + 1, cnt)\n                return\n            \n            len = min(n - x, m - y)\n            while len >= 1 and not isAvailable(x, y, len):\n                len -= 1\n            k = len\n            while k >= 1 and isAvailable(x, y, k):\n                fillUp(x, y, k, True)\n                # \u8df3\u8fc7 k \u4e2a\u4f4d\u7f6e\u5f00\u59cb\u68c0\u6d4b\n                dfs(x, y + k, cnt + 1)\n                fillUp(x, y, k, False)\n                k -= 1\n\n        def isAvailable(x: int, y: int, k: int) -> bool:\n            for i in range(k):\n                for j in range(k):\n                    if rect[x + i][y + j] == True:\n                        return False\n            return True\n        \n        def fillUp(x: int, y: int, k: int, val: bool) -> None:\n            for i in range(k):\n                for j in range(k):\n                    rect[x + i][y + j] = val\n\n        ans = max(n, m)\n        rect = [[False] * m for _ in range(n)]\n        dfs(0, 0, 0)\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.tilingRectangle(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
