    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def sumImbalanceNumbers(self, nums: List[int]) -> int:\n        n = len(nums)\n        # [[\u5b57\u5178\uff08\u8bb0\u5f55\u67d0\u4e2a\u6570\u5b57\u662f\u5426\u5b58\u5728\uff09\uff0c\u8be5\u957f\u5ea6\u4e0b\u7684\u5b50\u6570\u7ec4\u5df2\u7ecf\u5b58\u5728\u7684\u4e0d\u5e73\u8861\u6570\u5b57\u6570\u91cf]]\n        # info[0] \u4ee3\u8868\u4e0b\u68070\u5230\u5f53\u524d\u4e0b\u6807\u957f\u5ea6\u7684\u5b50\u6570\u7ec4\u4fe1\u606f\n        info = [[defaultdict(bool), 0] for _ in range(n)]\n        ans = 0\n        info[0][0][nums[0]] = True\n        \n        for i in range(1,n):\n            num = nums[i]\n            for j in range(i):\n                if not info[j][0][num]:\n                    if info[j][0][num - 1]: info[j][1] -= 1\n                    if not info[j][0][num + 1]: info[j][1] += 1\n                info[j][0][num] = True # \u5f80\u8fd9\u4e2aj-i\u957f\u5ea6\u7684\u5b57\u5178\u4e2d\u6dfb\u52a0\u65b0\u6570\u5b57\n                ans += info[j][1]\n            info[i][0][num] = True # \u610f\u4e3a\u5f53\u524d1\u957f\u5ea6\u7684\u5b57\u5178\u4e2d\u6dfb\u52a0\u65b0\u6570\u5b57\n            \n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.sumImbalanceNumbers(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
