    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def maximumRequests(self, n: int, requests: List[List[int]]) -> int:\n        delta = [0] * n\n        ans, cnt, zero = 0, 0, n\n\n        def dfs(pos: int) -> None:\n            nonlocal ans, cnt, zero\n            if pos == len(requests):\n                if zero == n:\n                    ans = max(ans, cnt)\n                return\n\n            # \u4e0d\u9009 requests[pos]\n            dfs(pos + 1)\n\n            # \u9009 requests[pos]\n            z = zero\n            cnt += 1\n            x, y = requests[pos]\n            zero -= delta[x] == 0\n            delta[x] -= 1\n            zero += delta[x] == 0\n            zero -= delta[y] == 0\n            delta[y] += 1\n            zero += delta[y] == 0\n            dfs(pos + 1)\n            delta[y] -= 1\n            delta[x] += 1\n            cnt -= 1\n            zero = z\n\n        dfs(0)\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maximumRequests(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
