    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1aarr1\u3001arr2\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def getXORSum(self, arr1: List[int], arr2: List[int]) -> int:\n        m, n = len(arr1), len(arr2)\n        ans = 0\n        \n        # \u4f9d\u6b21\u786e\u5b9a\u7b54\u6848\u4e8c\u8fdb\u5236\u8868\u793a\u4e2d\u7684\u6bcf\u4e00\u4f4d\n        for k in range(30, -1, -1):\n            cnt1 = sum(1 for num in arr1 if num & (1 << k))\n            cnt2 = sum(1 for num in arr2 if num & (1 << k))\n            # \u5982\u679c cnt1 \u548c cnt2 \u90fd\u662f\u5947\u6570\uff0c\u90a3\u4e48\u7b54\u6848\u7684\u7b2c k \u4f4d\u4e3a 1\n            if cnt1 % 2 == 1 and cnt2 % 2 == 1:\n                ans |= (1 << k)\n\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.getXORSum(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
