    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def maximumGood(self, statements: List[List[int]]) -> int:\n        n = len(statements)\n        ans = 0\n        for mask in range(1, 1 << n):\n            def check() -> bool:\n                for i in range(n):\n                    for j in range(n):\n                        if i == j:\n                            continue\n                        if statements[i][j] == 0:\n                            if mask & (1 << i) and mask & (1 << j):\n                                return False\n                        elif statements[i][j] == 1:\n                            if mask & (1 << i) and not mask & (1 << j):\n                                return False\n                return True\n            \n            if check():\n                ans = max(ans, bin(mask).count(\"1\"))\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maximumGood(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
